﻿using System;
using System.Collections.Generic;
using System.Text;
using System.IO;
namespace С_Generation
{
    class Program
    {
        static void Main(string[] args)
        {
            int n = int.Parse(Console.ReadLine());

            long sum = 0;
            long p = 1;
            while(n>0)
            {
                p *= 2;
                sum += p;
                n--;
            }
            Console.WriteLine(sum);
        }
    }
}
